def k_machine_schedule(jobs: list[list[int]], k: int) -> int:
    if not jobs:
        return 0
    times = sorted({t for s, e, _ in jobs for t in (s, e)})
    idx = {t: i for i, t in enumerate(times)}
    n = len(times)
    g = [[] for _ in range(n)]

    def add(u, v, cap, cost):
        g[u].append([v, len(g[v]), cap, cost])
        g[v].append([u, len(g[u]) - 1, 0, -cost])

    for i in range(n - 1):
        add(i, i + 1, k, 0)
    for s, e, p in jobs:
        add(idx[s], idx[e], 1, -p)

    total = 0
    for _ in range(k):
        dist = [float("inf")] * n
        prev = [None] * n
        dist[0] = 0
        for _ in range(n - 1):
            updated = False
            for u in range(n):
                if dist[u] == float("inf"):
                    continue
                for ei, e in enumerate(g[u]):
                    if e[2] > 0 and dist[u] + e[3] < dist[e[0]]:
                        dist[e[0]] = dist[u] + e[3]
                        prev[e[0]] = (u, ei)
                        updated = True
            if not updated:
                break
        v = n - 1
        while v != 0:
            u, ei = prev[v]
            e = g[u][ei]
            e[2] -= 1
            g[v][e[1]][2] += 1
            v = u
        total += dist[n - 1]

    return -total
